def build():
    questions = []
    passages = [{"key": "L1", "title": POEM1[0], "text": POEM1[1]}, {"key": "L2", "title": POEM2[0], "text": POEM2[1]}, {"key": "L3", "title": PROSE[0], "text": PROSE[1]}]
    for key, diff, q, a, b, c, d, ans, exp in LIT_PASSAGE:
        questions.append({"subject": "Literature in English", "topic": "Literary Appreciation", "passage": key, "difficulty": diff, "q": q, "A": a, "B": b, "C": c, "D": d, "answer": ans, "explanation": exp})
    for subject, rows in (("Literature in English", LIT), ("Christian Religious Studies", CRS), ("Islamic Religious Studies", IRS)):
        for topic, diff, q, a, b, c, d, ans, exp in rows:
            questions.append({"subject": subject, "topic": topic, "difficulty": diff, "q": q, "A": a, "B": b, "C": c, "D": d, "answer": ans, "explanation": exp})
    _balance(questions)
    texts = [x["q"] for x in questions]
    assert len(texts) == len(set(texts)), "duplicate question text"
    assert all(x["answer"] in "ABCD" and all(x[k] for k in "ABCD") for x in questions)
    batch = {
        "batch_id": "batch_004_lit_crs_irs",
        "exam_type": "JAMB",
        "note": "Literature: unseen poems/prose with appreciation questions + devices inside quoted lines; CRS and IRS: situation-based application of the set narratives.",
        "passages": passages,
        "questions": questions,
        "deactivate": [],
    }
    with open(OUT, "w", encoding="utf-8") as fh:
        json.dump(batch, fh, ensure_ascii=False, indent=1)
    from collections import Counter
    print(f"wrote {OUT}: {len(questions)} questions, {len(passages)} passages")
    print("answer letters:", dict(Counter(x['answer'] for x in questions)))
    print("per subject:", dict(Counter(x['subject'] for x in questions)))


if __name__ == "__main__":
    build()
